#!/usr/bin/env bash
# P0/P1 reviewer-hardening bundle:
#   1) LCB (Bonferroni) risk-controlled slow-tier selection  -> fixes SLO violation
#   2) cost-regime accounting (KV-fork / prefix-cache / black-box)
#   3) Proposition-2 empirical validation + Figure 2
#   4) MMLU-Pro benchmark (|A|=10) — falsifiable test of Prop. 2  + queue
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing P0/P1 reviewer-hardening bundle..."
decode "apply_lcb.py" << 'B64EOF'

B64EOF
decode "apply_mmlupro.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_cost_regimes.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_prop2_validate.py" << 'B64EOF'

B64EOF
decode "run_queue_mmlupro.sh" << 'B64EOF'

B64EOF
python apply_lcb.py && rm apply_lcb.py
python apply_mmlupro.py && rm apply_mmlupro.py
chmod +x run_queue_mmlupro.sh
echo ""
echo "Installed. Next:"
echo "  1) A/B the selection rule (this is the P0 result):"
echo "     TG_SELECT=point python scripts/ntc_genseed_agg.py ... --tag X_point"
echo "     TG_SELECT=lcb   python scripts/ntc_genseed_agg.py ... --tag X_lcb"
echo "  2) python scripts/ntc_cost_regimes.py --probes <files>"
echo "  3) python scripts/ntc_prop2_validate.py --probes <files>"
echo "  4) bash run_queue_mmlupro.sh --dry && bash run_queue_mmlupro.sh"